style.css:
/* Make the entire background black */
body, html {
  background-color: #000 !important;
  color: #fff !important;
}

/* Override backgrounds for most elements */
* {
  background-color: transparent !important;
  color: #fff !important;
  border-color: #444 !important;
}

/* Specific containers that may have their own background */
div, section, header, footer, nav, article, aside {
  background-color: #000 !important;
  color: #fff !important;
}

/* Invert image filters (for logos or icons that become invisible) */
img, svg {
  filter: invert(1) hue-rotate(180deg) !important;
}

/* Links */
a {
  color: #0af !important;
}

/* Remove box shadows if needed */
* {
  box-shadow: none !important;
}
